import{_ as t,o as a,a as i,b as r}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"数学计算","link":"/api/SIMD-API/adv_api/math_compute/math_compute"},{"text":"Acosh接口","link":"/api/SIMD-API/adv_api/math_compute/Acosh_interface/Acosh_interface"},{"text":"GetAcoshTmpBufferFactorSize","link":"/api/SIMD-API/adv_api/math_compute/Acosh_interface/GetAcoshTmpBufferFactorSize"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/math_compute/Acosh_interface/GetAcoshTmpBufferFactorSize.md","filePath":"api/SIMD-API/adv_api/math_compute/Acosh_interface/GetAcoshTmpBufferFactorSize.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1785895910000}'),o={name:"api/SIMD-API/adv_api/math_compute/Acosh_interface/GetAcoshTmpBufferFactorSize.md"};function h(c,e,p,d,s,n){return a(),i("div",null,[...e[0]||(e[0]=[r(`<div><article class="markdown-body"><h1>GetAcoshTmpBufferFactorSize</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>kernel侧Acosh接口的计算需要开发者预留/申请临时空间，最大临时空间（maxTmpBuffer）和输入所占空间（inputSize * typeSize）存在以下关系：</p><p><strong>maxTmpBuffer = maxLiveNodeCount * inputSize * typeSize + extraBuffer</strong></p><p>其中maxLiveNodeCount表示最大临时空间是输入所占空间的多少倍；extraBuffer表示使用的额外临时空间大小。</p><p>该接口用于获取maxLiveNodeCount和extraBuffer，在固定空间大小的情况下，通过maxLiveNodeCount和extraBuffer可以推算算子单次最大计算元素数量；另外，接口获取的maxLiveNodeCount值可能为0，计算时需要判断该值非0，避免除零错误。</p><p>示例如下：</p><p>算子实现需要调用Acosh接口，开发者为其预留currBuff大小的空间，利用GetAcoshTmpBufferFactorSize接口得到maxLiveNodeCount、extraBuffer输出值，反推Acosh算子单次最大计算元素数量为：</p><p><strong>currentShapeSize = (currBuff - extraBuffer) / maxLiveNodeCount / typeSize</strong></p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>void GetAcoshTmpBufferFactorSize(const uint32_t typeSize, uint32_t&amp; maxLiveNodeCount, uint32_t&amp; extraBuf)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数列表</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>typeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。比如输入的数据类型为half，此处应传入2。</td></tr><tr><td>maxLiveNodeCount</td><td>输出</td><td>最大存活节点数，最大临时空间是输入所占空间的多少倍。</td></tr><tr><td>extraBuf</td><td>输出</td><td>使用的额外临时空间大小，单位为字节。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>当利用maxLiveNodeCount，extraBuf反推出的currentShapeSize * typeSize &lt; 256B时，currentShapeSize按照256B/typeSize的值向上取整。</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 获取输入类型为half的Acosh操作的maxLiveNodeCount和extraBuffer
uint32_t typeSize = sizeof(half);
uint32_t maxLiveNodeCount = 0;
uint32_t extraBuffer = 0;

AscendC::GetAcoshTmpBufferFactorSize(typeSize, maxLiveNodeCount, extraBuffer);
</code></pre></div></article></div>`,1)])])}const f=t(o,[["render",h]]);export{u as __pageData,f as default};
